//! 📡️ The original outer request resumes with its exact child identity and native output through the defining JSON writer.
use super::*;
use super::encoding::FlowReplyEncodingFailure;
use flow::invocation_publication::FlowInvocationOrigin;
use semio_framework_pack_json::{JsonBorrowedWriteCursor,JsonWriteSource,JsonWriteNode};
use semio_framework_value::{NativeEncodeControl,NativeEncodeContinuation};
use flow::invocation_publication::FlowInvocationExternalResumeSource as ResumeSource;
#[derive(RetireOwned)]
struct Fields{writer:Option<JsonBorrowedWriteCursor>,continuation:Option<NativeEncodeContinuation>,output:Option<String>}
pub(crate) struct FlowExternalResumeRequestWork{fields:ManuallyDrop<Option<Fields>>,retirement:RetainedCloneClose,binding:Option<(OriginalSourceBinding,usize,usize,usize)>,phase:u8,closing:bool}
impl FlowExternalResumeRequestWork{
 pub(crate) fn new()->Self{Self{fields:ManuallyDrop::new(Some(Fields{writer:None,continuation:None,output:None})),retirement:Default::default(),binding:None,phase:0,closing:false}}
 pub(crate) fn step(&mut self,outer:&FlowInvocationOrigin,child:&FlowInvocationOrigin,output:&DslValue,syntax:&mut Option<FlowReplyEncodingFailure>,cx:&mut StepContext<'_>)->Result<Option<String>,OriginalTurnFailure>{for _ in 0..512{let before=(cx.retained_progress(),cx.original_total_fuel_remaining());if let Some(value)=self.once(outer,child,output,syntax,cx)?{return Ok(Some(value))}if syntax.is_some()||cx.should_yield()||cx.is_cancelled()||before==(cx.retained_progress(),cx.original_total_fuel_remaining()){break}}Ok(None)}
 fn once(&mut self,outer:&FlowInvocationOrigin,child:&FlowInvocationOrigin,output:&DslValue,syntax:&mut Option<FlowReplyEncodingFailure>,cx:&mut StepContext<'_>)->Result<Option<String>,OriginalTurnFailure>{
  let binding=(OriginalSourceBinding::borrow(cx),outer as*const _ as usize,child as*const _ as usize,output as*const _ as usize);if self.closing||syntax.is_some()||self.binding.is_some_and(|original|original!=binding)||child.outer_node_hash!=Some(outer.node_hash){return Err(invalid().into())}if cx.should_yield()||cx.is_cancelled(){return Ok(None)}
  let capture=2*size_of::<Option<String>>()+size_of::<Option<NativeEncodeContinuation>>();let fields=self.fields.as_mut().ok_or_else(invalid)?;
  if self.phase==0{let d=RetirementDemand{copy_bytes:size_of::<JsonBorrowedWriteCursor>()+size_of::<Option<(OriginalSourceBinding,usize,usize,usize)>>(),depth:1,..Default::default()};if !cx.retained_work_can_enter(d){return Ok(None)}self.binding=Some(binding);fields.writer=Some(JsonBorrowedWriteCursor::new());self.phase=1;cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})?;return Ok(None)}
  if self.phase==2{let d=RetirementDemand{copy_bytes:capture,depth:1,..Default::default()};if !cx.retained_work_can_enter(d){return Ok(None)}cx.consume_fuel(1);let output=fields.output.take();self.phase=4;let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if let Err(error)=cx.consume_retained(p){fields.output=output;self.phase=2;return Err(error.into())}return Ok(output)}
  if self.phase!=1{return Err(invalid().into())}let source=ResumeSource{outer,child,output};let writer=fields.writer.as_mut().ok_or_else(invalid)?;let copy=cx.retained_grant().maximum_copy_bytes.saturating_sub(capture);let mut d=writer.normal_step_demands_with_copy(&source,copy)?;d.copy_bytes=d.copy_bytes.checked_add(capture).ok_or_else(invalid)?;if !cx.retained_work_can_enter(d){return Ok(None)}
  let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,..cx.retained_grant()};let mut callback=|_|!cx.should_yield()&&!cx.is_cancelled();let mut control=match fields.continuation.take(){Some(original)=>match NativeEncodeControl::resume(original,&mut callback){Ok(control)=>control,Err((error,original))=>{fields.continuation=Some(original);return Err(error.into())}},None=>NativeEncodeControl::new_retained(&mut callback)};let result=writer.step(&source,1,&mut control,grant);let mut p=writer.normal_step_progress();let work=writer.last_turn_work();let continuation=control.pause().map_err(|(error,_)|error);
  let(error,continuation_refusal)=match(result,continuation){(Ok(value),Ok(continuation))=>{fields.output=value;fields.continuation=Some(continuation);(None,None)},(Err(error),Ok(continuation))=>{fields.continuation=Some(continuation);(Some(error),None)},(Ok(value),Err(error))=>{fields.output=value;(Some(error),None)},(Err(error),Err(refusal))=>(Some(error),Some(refusal))};
  if work!=0||p!=Default::default(){p.copied_bytes=p.copied_bytes.checked_add(capture).ok_or_else(invalid)?;}if let Some(error)=error{*syntax=Some(FlowReplyEncodingFailure{error,continuation_refusal,effects:p});self.phase=3}else if fields.output.is_some(){self.phase=2}cx.consume_fuel(work);cx.consume_retained(p)?;Ok(None)
 }
 pub(crate) fn restore_output(&mut self,value:String){assert_eq!(self.phase,4);self.fields.as_mut().expect("original external reply writer").output=Some(value);self.phase=2}
 pub(crate) fn begin_close(&mut self){self.closing=true}
 pub(crate) fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.fields.is_some(){return self.retirement.next_owner_demands::<Fields>(true,&None,body)}Ok(RetirementDemand{copy_bytes:size_of::<Option<(OriginalSourceBinding,usize,usize,usize)>>(),depth:usize::from(self.binding.is_some()),..Default::default()})}
 pub(crate) fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<Close,OriginalTurnFailure>{if !self.closing||self.binding.is_some_and(|binding|!binding.0.matches(cx)){return Err(invalid().into())}let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=close_with_effect(cx,d,|g,effect|{if !self.retirement.is_empty(){return poll_outcome(self.retirement.step_granted(g.maximum_copy_bytes,effect))}if self.fields.is_some(){return begin_close_owner(&mut self.retirement,&mut self.fields,effect)}if self.binding.is_none(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}self.binding=None;RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}})?;Ok(if self.terminal_is_empty(){Close::Complete{progress:step.progress()}}else{Close::Pending{progress:step.progress()}})}
 pub(crate) fn terminal_is_empty(&self)->bool{self.closing&&self.fields.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl Drop for FlowExternalResumeRequestWork{fn drop(&mut self){assert!(self.terminal_is_empty(),"original native external-result writer requires paid terminal closure");unsafe{ManuallyDrop::drop(&mut self.fields)}}}
